mapper.sql:
tenant_id = #{tenantId}
AND deleted = b'0'

    AND list_province = #{province}


    AND list_city = #{city}


    AND (list_name LIKE CONCAT('%', #{customerName}, '%')
    OR nature_name LIKE CONCAT('%', #{customerName}, '%'))


    AND industry = #{industry}


    AND (manager_a LIKE CONCAT('%', #{manager}, '%')
    OR manager_a_oa = #{manager}
    OR manager_b LIKE CONCAT('%', #{manager}, '%')
    OR manager_b_oa = #{manager}
    OR leader LIKE CONCAT('%', #{manager}, '%')
    OR leader_oa = #{manager})


    AND is_core = b'1'
